default_credential_patterns := {"admin", "password", "123456", "default", "guest"}

is_sensitive_key(name) {
    lower_name := lower(name)
    kw := credential_keywords[_]
    contains(lower_name, kw)
}

is_literal_value(node) {
    node.ir_type == "String"
    node.value != ""
} else {
    node.ir_type == "Integer"
} else {
    node.ir_type == "Float"
}

contains_base64_pattern(value) {
    regex.match("^[A-Za-z0-9+/]{20,}={0,2}$", value)
}

is_high_entropy_string(value) {
    count(value) > 20
    regex.match("[A-Za-z].*[0-9].*[^A-Za-z0-9]", value)
}

is_default_or_weak_credential(value) {
    pattern := default_credential_patterns[_]
    contains(lower(value), pattern)
} else {
    value == ""
}

has_encoding_obfuscation(node) {
    node.ir_type == "FunctionCall"
    f := unsafe_function_names[_]
    contains(lower(node.name), f)
}

is_unsafe_value(node) {
    is_literal_value(node)
    node.ir_type == "String"
    contains_base64_pattern(node.value)
} else {
    is_literal_value(node)
    node.ir_type == "String"
    is_high_entropy_string(node.value)
} else {
    is_literal_value(node)
    node.ir_type == "String"
    is_default_or_weak_credential(node.value)
} else {
    has_encoding_obfuscation(node)
}

has_unsafe_literal(node) {
    is_literal_value(node)
    is_unsafe_value(node)
} else {
    node.ir_type == "FunctionCall"
    arg := node.args[_]
    has_unsafe_literal(arg)
} else {
    node.ir_type == "MethodCall"
    arg := node.args[_]
    has_unsafe_literal(arg)
} else {
    node.ir_type == "Array"
    elem := node.value[_]
    has_unsafe_literal(elem)
} else {
    node.ir_type == "Hash"
    val := node.value[_]
    has_unsafe_literal(val)
} else {
    node.ir_type == "Sum"
    has_unsafe_literal(node.left)
} else {
    node.ir_type == "Sum"
    has_unsafe_literal(node.right)
} else {
    node.ir_type == "AddArgs"
    arg := node.value[_]
    has_unsafe_literal(arg)
}

is_safe_reference(node) {
    node.ir_type == "VariableReference"
} else {
    node.ir_type == "FunctionCall"
    not has_encoding_obfuscation(node)
    not is_literal_credential_source(node)
} else {
    node.ir_type == "MethodCall"
    not has_encoding_obfuscation(node)
}

is_literal_credential_source(node) {
    node.ir_type == "String"
    regex.match("\\.\\./|/etc/|/var/|/opt/|/home/|\\.pem|\\.key|\\.p12|\\.pfx|secret|credential|password|token", node.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := {n |
        walk(parent, [path, n])
        n.ir_type == "Attribute"
    }

