package glitch

import data.glitch_lib

credential_keywords := {"password", "passwd", "pwd", "secret", "token", "key", "api_key", "apikey", "access_key", "secret_key", "credential", "credentials", "private_key", "public_key", "ssh_key"}

unsafe_encoding_functions := {"base64encode", "base64", "jsonencode", "yamlencode", "md5", "sha1", "sha256"}

weak_password_patterns := {"password", "123456", "default", "guest", "qwerty", "123456789", "admin", "letmein", "welcome", "monkey", "password123"}

is_sensitive_key(name) {
    lower_name := lower(name)
    kw := credential_keywords[_]
    contains(lower_name, kw)
}

contains_base64_pattern(value) {
    regex.match("^[A-Za-z0-9+/]{20,}={0,2}$", value)
}

is_password_hash(value) {
    regex.match("^\\$[0-9][a-z]?\\$", value)
}

is_weak_password(value) {
    val := lower(value)
    pattern := weak_password_patterns[_]
    val == pattern
}

has_encoding_obfuscation(name) {
    lower_name := lower(name)
    f := unsafe_encoding_functions[_]
    contains(lower_name, f)
}

is_hardcoded_string(val) {
    val.ir_type == "String"
    val.value != ""
    not val.value == ""
}

is_safe_reference(val) {
    val.ir_type == "VariableReference"
} else {
    val.ir_type == "FunctionCall"
    not has_encoding_obfuscation(val.name)
}

has_unsafe_encoding_function(val) {
    walk(val, [_, n])
    n.ir_type == "FunctionCall"
    has_encoding_obfuscation(n.name)
}

is_suspicious_value(val) {
    val.ir_type == "String"
    contains_base64_pattern(val.value)
} else {
    val.ir_type == "String"
    is_password_hash(val.value)
} else {
    val.ir_type == "String"
    is_weak_password(val.value)
} else {
    has_unsafe_encoding_function(val)
}

should_detect_credential(key_name, val) {
    is_sensitive_key(key_name)
    is_hardcoded_string(val)
    not is_safe_reference(val)
} else {
    is_sensitive_key(key_name)
    is_suspicious_value(val)
    not is_safe_reference(val)
}

is_whitelist_username_key(key_name) {
    lower(key_name) == key_name
    contains(lower(key_name), "user")
    not contains(lower(key_name), "password")
    not contains(lower(key_name), "secret")
    not contains(lower(key_name), "token")
    not contains(lower(key_name), "key")
    not contains(lower(key_name), "credential")
}

is_whitelist_username_value(val) {
    val.ir_type == "String"
    common_users := {"root", "admin", "administrator", "user", "guest", "ubuntu", "centos", "ec2-user", "vagrant", "ansible", "deploy"}
    common_users[lower(val.value)]
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [path, node])

    node.ir_type == "Hash"
    entry := node.value[_]

    key_str := entry.key.value
    val := entry.value

    should_detect_credential(key_str, val)
    not (is_whitelist_username_key(key_str); is_whitelist_username_value(val))

    result := {
        "type": "sec_hard_secr",
        "element": entry,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Avoid embedding credentials directly in source code. Use secure credential management instead. (CWE-798)"
    }
}

