    parent.path != ""

    attrs := {n |
        walk(parent, [path, n])
        n.ir_type == "Attribute"
    }

    attr := attrs[_]
    should_detect_credential(attr.name, attr.value)
    not (is_whitelist_username_key(attr.name); is_whitelist_username_value(attr.value))

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Avoid embedding credentials directly in source code. Use secure credential management instead. (CWE-798)"
